import React, { Component } from 'react';
import { CButton, CCard, CCardBody, CCol, CContainer, CInput, CRow } from '@coreui/react';
import Select from 'react-select';
import { requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const FILE_NAME = "ListActions.js";

const PRIORITY_OPTIONS = [
    { value: 'P0', label: 'P0' },
    { value: 'P1', label: 'P1' },
    { value: 'P2', label: 'P2' },
];

const STATUS_OPTIONS = [
    { value: 'TODO', label: 'TODO' },
    { value: 'WIP', label: 'WIP' },
    { value: 'DONE', label: 'DONE' },
];

const SORT_BY_OPTIONS = [
    { value: 'CREATED_DATE', label: 'Created date' },
    { value: 'START_DATE', label: 'Start date' },
    { value: 'DUE_DATE', label: 'Due date' },
];

const SORT_DIR_OPTIONS = [
    { value: 'DESC', label: 'Descending' },
    { value: 'ASC', label: 'Ascending' },
];

const PRIORITY_COLORS = { P0: '#e53e3e', P1: '#dd6b20', P2: '#3182ce' };
const STATUS_COLORS = { TODO: '#718096', WIP: '#3182ce', DONE: '#38a169' };

class ListActions extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            error: null,
            actions: [],
            subprograms: [],
            persons: [],
            programs: [],
            // filters
            selectedPersons: [],
            selectedSubprograms: [],
            selectedPriorities: [],
            selectedStatuses: [],
            hideDone: true,
            // Program-type preference is shared across views (TimeLogs, Actions, ...) and
            // persisted under the generic 'programTypeFilter' localStorage key. '' = All Types.
            programTypeFilter: localStorage.getItem('programTypeFilter') !== null ? localStorage.getItem('programTypeFilter') : 'WORK',
            search: '',
            sortBy: 'CREATED_DATE',
            sortDirection: 'DESC',
        };
    }

    componentDidMount() {
        document.title = "Actions";
        this.fetchReferenceData().then(() => this.fetchActions());
    }

    fetchReferenceData = () => {
        const userData = getUserDataFromLocalStorage();
        const subprogramPayload = JSON.stringify({ page: 1, size: 0 });
        const personPayload = JSON.stringify({ page: 1, size: 0 });
        const programPayload = JSON.stringify({ page: 1, size: 0 });

        return Promise.all([
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/sub-program/list', requestHeaderPOSTWithAuth(subprogramPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/person/list', requestHeaderPOSTWithAuth(personPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/program/list', requestHeaderPOSTWithAuth(programPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
        ])
        .then(([subprogramsResult, personsResult, programsResult]) => {
            this.setState({
                subprograms: (subprogramsResult && subprogramsResult.data) || [],
                persons: (personsResult && personsResult.data) || [],
                programs: (programsResult && programsResult.data) || [],
            });
        })
        .catch(error => Logger(FILE_NAME, "fetchReferenceData", "ERROR", "error", error));
    }

    fetchActions = () => {
        const {
            selectedPersons, selectedSubprograms, selectedPriorities, selectedStatuses, hideDone, programTypeFilter,
            search, sortBy, sortDirection
        } = this.state;

        // Resolve the statuses sent to the API. When "hide DONE" is on, we only ever
        // pass TODO/WIP: either the user's selection intersected with those, or both of
        // them when nothing is explicitly selected.
        let statuses = selectedStatuses.length > 0 ? selectedStatuses.map(o => o.value) : null;
        if (hideDone) {
            const base = statuses || ['TODO', 'WIP'];
            statuses = base.filter(s => s !== 'DONE');
        }

        const payload = {
            personIds: selectedPersons.length > 0 ? selectedPersons.map(o => Number(o.value)) : null,
            subprogramIds: selectedSubprograms.length > 0 ? selectedSubprograms.map(o => Number(o.value)) : null,
            priorities: selectedPriorities.length > 0 ? selectedPriorities.map(o => o.value) : null,
            statuses: statuses,
            programType: programTypeFilter || null,
            search: search.trim() || null,
            sortBy,
            sortDirection,
        };

        Logger(FILE_NAME, "fetchActions", "", "payload", payload);
        this.setState({ isLoaded: false, error: null });

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/action/list';

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(payload), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchActions", "SUCCESS", "count", (result.data || []).length);
            this.setState({ isLoaded: true, actions: result.data || [] });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchActions", "ERROR", "error", error);
            this.setState({ isLoaded: true, error: error.message });
        });
    }

    // Program-type is a sticky, cross-view preference: persist it to the shared
    // localStorage key and refetch. Deliberately NOT reset by clearFilters.
    onProgramTypeFilterChange = (e) => {
        const value = e.target.value;
        localStorage.setItem('programTypeFilter', value);
        this.setState({ programTypeFilter: value }, () => this.fetchActions());
    }

    clearFilters = () => {
        this.setState({
            selectedPersons: [],
            selectedSubprograms: [],
            selectedPriorities: [],
            selectedStatuses: [],
            hideDone: true,
            search: '',
            sortBy: 'CREATED_DATE',
            sortDirection: 'DESC',
        }, () => this.fetchActions());
    }

    getProgramName = (programId) => {
        const prog = this.state.programs.find(p => p.id === programId);
        return prog ? prog.name : programId;
    }

    // Builds the "<Program> / <Sub-program>" label, resolving the parent program
    // name via the programs lookup. Falls back to just the sub-program name.
    getSubprogramLabel = (subprogram) => {
        const prog = this.state.programs.find(p => p.id === subprogram.programId);
        return prog ? prog.name + ' / ' + subprogram.name : subprogram.name;
    }

    getSubprogramName = (subprogramId) => {
        if (!subprogramId) return '—';
        const p = this.state.subprograms.find(pr => pr.id === subprogramId);
        return p ? this.getSubprogramLabel(p) : subprogramId;
    }

    getPersonName = (personId) => {
        if (!personId) return '—';
        const p = this.state.persons.find(pe => pe.id === personId);
        return p ? p.name : personId;
    }

    renderEntityLink = (href, label) => {
        return (
            <a href={href} target="_blank" rel="noopener noreferrer"
                style={{ color: '#2b6cb0', textDecoration: 'none' }}
                onClick={(e) => e.stopPropagation()}>
                {label}
            </a>
        );
    }

    renderBadge(text, color) {
        return (
            <span style={{ background: color, color: 'white', borderRadius: '10px', padding: '2px 10px', fontWeight: 600, fontSize: '0.78em' }}>
                {text}
            </span>
        );
    }

    // Same relative-to-today highlight as ViewAction, but keyed off the given action's
    // status (each table row is a different action). Only highlights while NOT done.
    //   past → red, today → yellow, future / no date / DONE → no highlight.
    // Dates are plain yyyy-MM-dd, so compare on local calendar day.
    getDateHighlightStyle = (dateStr, status) => {
        if (!dateStr || status === 'DONE') return null;

        const parts = dateStr.split('-');
        if (parts.length !== 3) return null;
        const target = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
        target.setHours(0, 0, 0, 0);

        const today = new Date();
        today.setHours(0, 0, 0, 0);

        if (target < today) {
            return { background: '#fed7d7', color: '#742a2a', borderRadius: '6px', padding: '2px 8px', fontWeight: 600 };
        }
        if (target.getTime() === today.getTime()) {
            return { background: '#fefcbf', color: '#744210', borderRadius: '6px', padding: '2px 8px', fontWeight: 600 };
        }
        return null;
    }

    // Formats a plain yyyy-MM-dd date as "2026-10-05 Mon" (weekday after the date),
    // parsing on local calendar day so the weekday matches the stored date.
    formatDateWithWeekday = (dateStr) => {
        const parts = dateStr.split('-');
        if (parts.length !== 3) return dateStr;
        const d = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
        if (isNaN(d.getTime())) return dateStr;
        return dateStr + ' ' + d.toLocaleDateString(undefined, { weekday: 'short' });
    }

    // Renders an action date (start/due) with weekday suffix + relative highlight.
    renderActionDate = (dateStr, status) => {
        if (!dateStr) return '—';
        const label = this.formatDateWithWeekday(dateStr);
        const highlight = this.getDateHighlightStyle(dateStr, status);
        return highlight ? <span style={highlight}>{label}</span> : <span>{label}</span>;
    }

    render() {
        const {
            isLoaded, error, actions, subprograms, persons,
            selectedPersons, selectedSubprograms, selectedPriorities, selectedStatuses, hideDone, programTypeFilter,
            search, sortBy, sortDirection
        } = this.state;

        const subprogramOptions = subprograms.map(p => ({ value: String(p.id), label: this.getSubprogramLabel(p) }));
        const personOptions = persons.map(p => ({ value: String(p.id), label: p.name }));

        return (
            <div>
                <CContainer>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px', flexWrap: 'wrap', gap: '8px' }}>
                        <h1 style={{ margin: 0 }}>✅ Actions</h1>
                        <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                            <select
                                value={programTypeFilter}
                                onChange={this.onProgramTypeFilterChange}
                                title="Program type"
                                style={{ padding: '6px 10px', borderRadius: '6px', border: '1px solid #d8dbe0', background: '#fff', fontWeight: 600, cursor: 'pointer' }}
                            >
                                <option value="">All Types</option>
                                <option value="WORK">🏢 WORK</option>
                                <option value="PERSONAL">🏠 PERSONAL</option>
                            </select>
                            <CButton color="info" onClick={this.fetchActions}>🔄 Reload</CButton>
                            <a href="#/actions/create" style={{ textDecoration: 'none' }}>
                                <CButton color="success">➕ Create Action</CButton>
                            </a>
                        </div>
                    </div>

                    {/* Filters */}
                    <CCard className="mb-4">
                        <CCardBody>
                            <CRow>
                                <CCol md="3" className="mb-3">
                                    <label><strong>Persons</strong></label>
                                    <Select isMulti closeMenuOnSelect={false} placeholder="All persons"
                                        options={personOptions} value={selectedPersons}
                                        onChange={(vals) => this.setState({ selectedPersons: vals || [] })} />
                                </CCol>
                                <CCol md="3" className="mb-3">
                                    <label><strong>Sub-programs</strong></label>
                                    <Select isMulti closeMenuOnSelect={false} placeholder="All sub-programs"
                                        options={subprogramOptions} value={selectedSubprograms}
                                        onChange={(vals) => this.setState({ selectedSubprograms: vals || [] })} />
                                </CCol>
                                <CCol md="3" className="mb-3">
                                    <label><strong>Priorities</strong></label>
                                    <Select isMulti closeMenuOnSelect={false} placeholder="All priorities"
                                        options={PRIORITY_OPTIONS} value={selectedPriorities}
                                        onChange={(vals) => this.setState({ selectedPriorities: vals || [] })} />
                                </CCol>
                                <CCol md="3" className="mb-3">
                                    <label><strong>Statuses</strong></label>
                                    <Select isMulti closeMenuOnSelect={false} placeholder="All statuses"
                                        options={STATUS_OPTIONS} value={selectedStatuses}
                                        onChange={(vals) => this.setState({ selectedStatuses: vals || [] })} />
                                </CCol>
                            </CRow>

                            <CRow>
                                <CCol md="3" className="mb-3">
                                    <label><strong>Order by</strong></label>
                                    <Select options={SORT_BY_OPTIONS}
                                        value={SORT_BY_OPTIONS.find(o => o.value === sortBy) || null}
                                        onChange={(opt) => this.setState({ sortBy: opt ? opt.value : 'CREATED_DATE' })} />
                                </CCol>
                                <CCol md="3" className="mb-3">
                                    <label><strong>Direction</strong></label>
                                    <Select options={SORT_DIR_OPTIONS}
                                        value={SORT_DIR_OPTIONS.find(o => o.value === sortDirection) || null}
                                        onChange={(opt) => this.setState({ sortDirection: opt ? opt.value : 'DESC' })} />
                                </CCol>
                            </CRow>

                            <CRow>
                                <CCol md="6" className="mb-3">
                                    <label><strong>Search</strong> (title, description, comments)</label>
                                    <CInput placeholder="Search…" value={search}
                                        onChange={(e) => this.setState({ search: e.target.value })}
                                        onKeyDown={(e) => { if (e.key === 'Enter') this.fetchActions(); }} />
                                </CCol>
                                <CCol md="6" className="mb-3 d-flex align-items-end justify-content-between">
                                    <label style={{ display: 'flex', alignItems: 'center', gap: '8px', margin: 0, cursor: 'pointer', userSelect: 'none' }}>
                                        <input
                                            type="checkbox"
                                            checked={hideDone}
                                            onChange={(e) => this.setState({ hideDone: e.target.checked }, () => this.fetchActions())}
                                        />
                                        <strong>Don't show DONE</strong>
                                    </label>
                                    <div className="d-flex align-items-end">
                                        <CButton color="primary" className="mr-2" onClick={this.fetchActions}>🔍 Apply</CButton>
                                        &nbsp;
                                        <CButton color="light" onClick={this.clearFilters}>Clear</CButton>
                                    </div>
                                </CCol>
                            </CRow>
                        </CCardBody>
                    </CCard>

                    {/* Results */}
                    {!isLoaded && <Loading />}
                    {isLoaded && error && (
                        <div style={{ textAlign: 'center', padding: '30px', color: '#e53e3e', background: '#fff5f5', borderRadius: '10px', border: '1px solid #fed7d7' }}>
                            ⚠️ Error: {error}
                        </div>
                    )}
                    {isLoaded && !error && actions.length === 0 && (
                        <div style={{ textAlign: 'center', padding: '30px', color: '#888' }}>No actions match these filters.</div>
                    )}
                    {isLoaded && !error && actions.length > 0 && (
                        <CCard>
                            <CCardBody style={{ padding: 0 }}>
                                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                    <thead>
                                        <tr style={{ background: '#f7fafc', textAlign: 'left' }}>
                                            <th style={styles.th}>Title</th>
                                            <th style={styles.th}>Priority</th>
                                            <th style={styles.th}>Status</th>
                                            <th style={styles.th}>Sub-program</th>
                                            <th style={styles.th}>Person</th>
                                            <th style={styles.th}>Est. (hrs)</th>
                                            <th style={styles.th}>Start</th>
                                            <th style={styles.th}>Due</th>
                                            <th style={styles.th}>Created</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {actions.map(a => (
                                            <tr key={a.id} style={styles.row}>
                                                <td style={styles.td}>
                                                    <a href={'#/actions/' + a.id} target="_blank" rel="noopener noreferrer"
                                                        style={{ fontWeight: 600, color: '#2b6cb0', textDecoration: 'none' }}>
                                                        {a.title}
                                                    </a>
                                                </td>
                                                <td style={styles.td}>{this.renderBadge(a.priority, PRIORITY_COLORS[a.priority] || '#718096')}</td>
                                                <td style={styles.td}>{this.renderBadge(a.status, STATUS_COLORS[a.status] || '#718096')}</td>
                                                <td style={styles.td}>
                                                    {a.subprogramId
                                                        ? this.renderEntityLink('#/sub-program/' + a.subprogramId, this.getSubprogramName(a.subprogramId))
                                                        : '—'}
                                                </td>
                                                <td style={styles.td}>
                                                    {a.personId
                                                        ? this.renderEntityLink('#/person/' + a.personId, this.getPersonName(a.personId))
                                                        : '—'}
                                                </td>
                                                <td style={styles.td}>{(a.timeEstimateInHours === null || a.timeEstimateInHours === undefined) ? '—' : a.timeEstimateInHours}</td>
                                                <td style={styles.td}>{this.renderActionDate(a.startDate, a.status)}</td>
                                                <td style={styles.td}>{this.renderActionDate(a.dueDate, a.status)}</td>
                                                <td style={styles.td}>{a.createdOn ? new Date(a.createdOn).toLocaleDateString() : '—'}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </CCardBody>
                        </CCard>
                    )}
                </CContainer>
            </div>
        );
    }
}

const styles = {
    th: { padding: '12px 14px', fontSize: '0.85em', color: '#4a5568', borderBottom: '2px solid #e2e8f0' },
    td: { padding: '10px 14px', borderBottom: '1px solid #edf2f7', fontSize: '0.9em' },
    row: {},
};

export default ListActions;
